-- 454_hidden_curated_2.sql — #454 Charlotte story batch, part 2: 9 HIDDEN storyless OSM pins from the gate/leads union brought
-- back with a story (drafted 2026-11-04). Same shape and rules as 454_hidden_curated.sql: exact stored name at the stored
-- coordinate, read from the stored places:v34 rows on 2026-11-04; every pin passes #542 by pin id (its containing tile stores it);
-- no same-name pin or gem within 2 km (#519 (1)); no Wikipedia pin within 300 m; every sentence's numbers and names are in its
-- source. Air Midwest Flight 5481's article is in no stored tile, so the memorial carries the story. The union's #542 failures
-- are seeds in names-454-charlotte-2.txt; every union verdict is in 454_gate_drops_charlotte.tsv.
-- Batch file — run in the Mac session after the seed commit and after 454_hidden_curated.sql, then
-- curated_category_backfill(true). Expect 9 returned names, first "Firebird"; "Success. No rows returned" means the guard
-- skipped (already run — FROM RIVERSIDE (7)).
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Firebird$t$, 35.2243618::double precision, -80.8474951::double precision, $t$French-American artist Niki de Saint Phalle made this 17-foot, 1,400-pound bird in 1991 and covered it in more than 7,500 pieces of mirrored and colored glass; museum founder Andreas Bechtler bought it, it went up outside his museum in 2009, and locals call it the Disco Chicken.$t$, $t$https://uptowncharlotte.com/art/the-firebird-by-niki-de-sainte-phalle$t$, $t$#454 hidden-pin row (part 2): osm_node5016558822, stored in 704_-1617, 705_-1617; containing tile 704_-1617 stores it (#542)$t$),
  ($t$Spiral Odyssey$t$, 35.2264028::double precision, -80.8477692::double precision, $t$Chicago sculptor Richard Hunt made this welded stainless-steel tribute to Romare Bearden, nearly 30 feet tall and about 8,000 pounds, unveiled in 2017; he and Bearden were the first African-American artists to have solo shows at the Museum of Modern Art, both in 1971.$t$, $t$https://beardenfoundation.org/spiral-odyssey-sculpture-unveiled-at-the-romare-bearden-park/$t$, $t$#454 hidden-pin row (part 2): osm_node5016558838, stored in 704_-1617, 705_-1617; containing tile 705_-1617 stores it (#542)$t$),
  ($t$Liberty Hall Monument$t$, 35.2250875::double precision, -80.8458057::double precision, $t$The Liberty Hall Chapter of the Daughters of the American Revolution raised this granite pedestal, once topped by a sundial, in 1913 for Liberty Hall, the renamed Queen's College chartered in 1777, which closed in 1780 when Cornwallis moved his troops into Charlotte and never reopened.$t$, $t$https://docsouth.unc.edu/commland/monument/942/$t$, $t$#454 hidden-pin row (part 2): osm_node5016558835, stored in 704_-1617, 705_-1617; containing tile 705_-1617 stores it (#542)$t$),
  ($t$William Ewen Shipp Monument$t$, 35.2298763::double precision, -80.846687::double precision, $t$Dedicated on May 20, 1902, with the encouragement of Theodore Roosevelt, who served with him in Cuba, this monument honors First Lieutenant William Ewen Shipp, born near Asheville in 1861, raised in Lincolnton and the first southerner to graduate from West Point after the Civil War.$t$, $t$https://www.hmdb.org/m.asp?m=233378$t$, $t$#454 hidden-pin row (part 2): osm_node5016500329, stored in 704_-1617, 705_-1617; containing tile 705_-1617 stores it (#542)$t$),
  ($t$Vietnam Veterans' Memorial$t$, 35.2166724::double precision, -80.8337911::double precision, $t$This arched wall, dedicated in 1989, lists the 105 Mecklenburg County servicemen who died in Vietnam in the order of their deaths, beside a timeline of the war from 1959 to 1975 and lines written by a local Vietnam veteran.$t$, $t$https://www.legion.org/memorials/united-states/north-carolina/united-states-north-carolina-mecklenburg-county-vietnam-veterans-memorial-charlotte$t$, $t$#454 hidden-pin row (part 2): osm_node1443710808, stored in 704_-1616, 704_-1617, 705_-1617; containing tile 704_-1617 stores it (#542)$t$),
  ($t$Queen Charlotte Walks in Her Garden$t$, 35.227096::double precision, -80.840571::double precision, $t$This life-size bronze shows the city's namesake walking in her garden with two of her dogs; its plaque recalls a queen who bore 15 children, played the harpsichord, learned botany and took pleasure in Kew, and whose dog Presto followed her on daily walks.$t$, $t$https://ncpedia.org/monument/queen-charlotte-walks-her$t$, $t$#454 hidden-pin row (part 2): osm_node5016558837, stored in 704_-1617, 705_-1617; containing tile 705_-1617 stores it (#542)$t$),
  ($t$William Henry Belk$t$, 35.2127189::double precision, -80.8363268::double precision, $t$This Trail of History statue honors William Henry Belk, who started with a small dry goods store in Monroe, North Carolina, and built the Charlotte-based Belk stores into one of the leading retail enterprises in the Southeast.$t$, $t$https://www.charlottetrailofhistory.org/_files/ugd/7760c9_b3cf6ff9ccf74157a1600fe62ef32b91.pdf$t$, $t$#454 hidden-pin row (part 2): osm_node4676919717, stored in 704_-1616, 704_-1617; containing tile 704_-1617 stores it (#542)$t$),
  ($t$Air Midwest Flight 5481 Memorial$t$, 35.205242::double precision, -80.9445614::double precision, $t$This memorial remembers the 21 passengers and crew killed on January 8, 2003, when Air Midwest Flight 5481, a Beechcraft 1900D bound for Greenville–Spartanburg, stalled on takeoff from Charlotte Douglas and crashed into an aircraft hangar.$t$, $t$https://en.wikipedia.org/wiki/Air_Midwest_Flight_5481$t$, $t$#454 hidden-pin row (part 2): osm_node6581964391, stored in 704_-1618, 704_-1619; containing tile 704_-1619 stores it (#542)$t$),
  ($t$Morris Field$t$, 35.2033978::double precision, -80.9275107::double precision, $t$The Army Air Forces took over the city airport in early 1941 as Charlotte Air Base, renamed it Morris Field soon after Pearl Harbor and flew Third Air Force antisubmarine patrols and training from it before returning it to the City of Charlotte in 1946.$t$, $t$https://en.wikipedia.org/wiki/Charlotte_Douglas_International_Airport$t$, $t$#454 hidden-pin row (part 2): osm_node13645924712, stored in 704_-1618, 704_-1619; containing tile 704_-1619 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
